    // and the five predicates added (`__S: ?Sized + async::Tr<__S>`, `U: gen::Tr<__S>`,
    // `U: dyn::Tr<__S>`, `__S: gen::Tr<U>`, `&'a __S: dyn::Tr<u8>`), so 11; two impls.
    assert_eq!(names, 22, "{text}");
